def en_buyuk_pencere(a, k):
    s = best = sum(a[:k])
    for i in range(k, len(a)): s += a[i] - a[i - k]; best = max(best, s)
    return best
print(en_buyuk_pencere([2, 1, 5, 1, 3, 2], 3))

def canta(agirlik, deger, W):
    dp = [0] * (W + 1)
    for w, v in zip(agirlik, deger):
        for c in range(W, w - 1, -1): dp[c] = max(dp[c], dp[c - w] + v)
    return dp[W]
print(canta([1, 3, 4], [15, 20, 30], 4))
